use std::{fs,path::PathBuf};
use floatboard_storage::{now,store::Store};
use serde_json::{json,Value};
struct Temp(PathBuf);
impl Temp{fn new()->Self{let path=std::env::temp_dir().join(format!("floatboard-retention-{}",uuid::Uuid::new_v4().simple()));fs::create_dir_all(&path).unwrap();Self(path)}}
impl Drop for Temp{fn drop(&mut self){let _=fs::remove_dir_all(&self.0);}}
fn event(kind:&str,at:f64)->Value{json!({"event_id":uuid::Uuid::new_v4().simple().to_string(),"recorded_at":at,"kind":kind,"session_id":"fixture","host_id":"test","cwd":"C:/temp","tool_name":"private-runtime-tool"})}
fn report(revision:i64,title:&str,status:&str,at:f64)->Value{let mut e=event("progress",at);e["report"]=json!({"revision":revision,"title":title,"status":status,"plan":[{"id":"step","title":"fixture step","status":if status=="completed"{"completed"}else{"inProgress"}}],"evidence":if status=="completed"{json!([{"label":"fixture evidence"}])}else{json!([])},"blockers":[]});e}
#[test]fn hook_placeholders_hidden_but_dedup_and_plan_only_preserved(){let temp=Temp::new();let mut store=Store::open(&temp.0,false).unwrap();let hook=event("SessionStart",now()-20.);assert!(store.ingest(&hook).unwrap());assert!(!store.ingest(&hook).unwrap());assert!(store.tasks().unwrap().is_empty());assert_eq!(store.revision("fixture","test").unwrap(),-1);let saved:String=store.db.query_row("select payload from events",[],|r|r.get(0)).unwrap();assert_eq!(saved,"{}");let mut plan=event("plan",now()-10.);plan["plan"]=json!([{"id":"s","title":"真实计划","status":"inProgress"}]);store.ingest(&plan).unwrap();let tasks=store.tasks().unwrap();assert_eq!(tasks.len(),1);assert_eq!(tasks[0]["title"],"真实计划");assert!(!tasks[0].as_object().unwrap().contains_key("history"));assert!(tasks[0]["timing"]["started_at"].as_f64().is_some());}
#[test]fn completed_episode_survives_same_session_reuse_and_restart_with_frozen_timing(){let temp=Temp::new();let at=now()-100.;let mut store=Store::open(&temp.0,false).unwrap();store.ingest(&report(0,"first","running",at)).unwrap();store.ingest(&report(1,"first","completed",at+20.)).unwrap();store.ingest(&report(2,"first revised","completed",at+21.)).unwrap();assert_eq!(store.tasks().unwrap().len(),1);let n:i64=store.db.query_row("select count(*) from completed_tasks",[],|r|r.get(0)).unwrap();assert_eq!(n,1);store.ingest(&report(3,"second","running",at+30.)).unwrap();drop(store);let mut store=Store::open(&temp.0,false).unwrap();let tasks=store.tasks().unwrap();assert_eq!(tasks.len(),2);let archive=tasks.iter().find(|t|t["archived"]==true).unwrap();assert_eq!(archive["source_task_id"],"test:fixture");assert_eq!(archive["title"],"first revised");assert!(archive["id"].as_str().unwrap().starts_with("archive:"));assert_eq!(archive["timing"]["seconds"],20.);assert_eq!(archive["plan"][0]["timing"]["seconds"],20.);assert_eq!(store.revision("fixture","test").unwrap(),3);store.ingest(&report(4,"second","completed",at+40.)).unwrap();let tasks=store.tasks().unwrap();assert_eq!(tasks.len(),2);assert_eq!(tasks.iter().filter(|t|t["status"]=="completed").count(),2);let n:i64=store.db.query_row("select count(*) from completed_tasks",[],|r|r.get(0)).unwrap();assert_eq!(n,2);drop(store);let mut store=Store::open(&temp.0,true).unwrap();assert_eq!(store.tasks().unwrap().len(),2);}
#[test]fn payload_minimization_preserves_timer_replay_and_never_keeps_activity_history(){let temp=Temp::new();let at=now()-100.;let mut store=Store::open(&temp.0,false).unwrap();store.ingest(&report(0,"timer","running",at)).unwrap();store.ingest(&event("PreToolUse",at+10.)).unwrap();store.ingest(&report(1,"timer","completed",at+25.)).unwrap();let before=store.tasks().unwrap();let payloads:Vec<String>=store.db.prepare("select payload from events").unwrap().query_map([],|r|r.get(0)).unwrap().map(Result::unwrap).collect();assert!(!payloads.join("").contains("private-runtime-tool"));assert!(!payloads.join("").contains("cwd"));drop(store);let mut store=Store::open(&temp.0,true).unwrap();let after=store.tasks().unwrap();assert_eq!(before,after);assert_eq!(after[0]["timing"]["seconds"],25.);assert!(!after[0].as_object().unwrap().contains_key("history"));}
